,'sections',jsonb_build_array(jsonb_build_object('key','musculoskeletal','title','Musculoskeletal','sequence',10,'description','Mapped from legacy form_ros musculoskeletal fields.')),'fields',value,'rules','[]'::jsonb) schema_json from fields)
